"""Report failed baseline feasibility honestly; no storm traffic on unqualified loads."""
from observed_load_common_v1 import *
import html,datetime as dt
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def main():
 gate=json.loads((R/'feasibility_gate.json').read_text());v=json.loads((R/'validation.json').read_text());basis=json.loads((R/'basis_validation.json').read_text());fit=json.loads((R/'inverse_summary.json').read_text());prep=json.loads((R/'preparation_summary.json').read_text());assert v['passed']and basis['passed'];o=pd.read_csv(P/'normal_observation_constraints.csv');metrics=pd.read_csv(P/'normal_constraint_metrics.csv');dep=pd.read_csv(P/'fixed_route_flow_dependency.csv').iloc[0];cov=pd.read_csv(P/'structural_coverage_summary.csv');plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'figure.facecolor':'#f5f8fa'})
 fig,(ax,bx)=plt.subplots(1,2,figsize=(12,5.2));supported=cov.route_supported_screens.to_numpy();missing=cov.structural_uncovered_screens.to_numpy();ax.bar([0,1],supported,color='#387f99',label='Existing route support');ax.bar([0,1],missing,bottom=supported,color='#b9684c',label='No existing prior route');ax.set_xticks([0,1],['Ordinary roads','Expressways']);ax.set(ylim=(0,65),ylabel='Observed screenlines',title='Observed support: 80 of 85')
 for i,(a,b)in enumerate(zip(supported,missing)):ax.text(i,a/2,str(a),ha='center',color='white');ax.text(i,a+b+1,f'{a+b} total',ha='center')
 ax.legend(frameon=False,fontsize=8)
 y=np.array([dep.first_observed_small12h,dep.second_observed_small12h])/1000;bx.barh([1,0],y,color=['#b88741','#387f99'],height=.45,alpha=.7);bx.errorbar(y,[1,0],xerr=y*.2,fmt='o',color='#273f4c',capsize=5);bx.set_yticks([1,0],['A: 13200010050','B: 13200010110']);bx.set(xlim=(0,80),xlabel='Observed small-vehicle passages / 12h (thousands)',title='Fixed existing routes require modeled A <= modeled B')
 for yy,xx in zip([1,0],y):bx.text(xx+1,yy+.27,f'{xx:.2f}k',fontsize=9)
 fig.tight_layout(rect=[0,.22,1,.95]);fig.suptitle('Baseline gate failed: OD reweighting alone cannot meet the fixed-route constraints',fontsize=12);fig.text(.5,.04,'Error bars: preregistered +/-20% observation bands, not confidence intervals.\nWithin the current existing route pool, every passage counted at A also contributes at B.\n80%-of-A = 47,558 > 120%-of-B = 18,923. Independent LP minimum necessary uniform error band: +/-58.07%.\nThis diagnoses the route/OD-support or observation-mapping relationship, not an error in the official observations.',ha='center',fontsize=8);fig.savefig(R/'baseline_gate_evidence.png',dpi=170);plt.close(fig)
 def link(n,label):return f'<a href="{os.path.relpath(P/n,R)}">{html.escape(label)}</a>'
 rows=''.join(f'<tr><td>{r.load}</td><td>{"普通道路"if r.road_class=="ordinary"else"高速"}</td><td>{r.scenario_small12h_passages/r.observed_small12h:.2%}</td><td>{r.wape_all:.2%}</td><td>{r.supported_within20_count}/{r.supported_screens}</td></tr>'for r in metrics.itertuples());cert=''.join(f'<tr><td>{r["observation_section_id"]}</td><td>{html.escape(r["source_route_name"])}</td><td>{r["observed_small12h"]:,.0f}</td><td>{"模型上界约束"if r["direction_of_constraint"]=="upper"else"模型下界约束"}</td></tr>'for r in gate['certificate_active_constraints']);counts=len(v['checks'])+len(basis['checks'])
 doc=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>观测约束交通负荷：准入失败诊断</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#edf2f5;color:#233e4b;font:16px/1.75 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}}main{{max-width:1120px;margin:30px auto;padding:32px;background:#fff;border-radius:16px}}h1{{font-size:29px;line-height:1.4}}h2{{font-size:22px;margin-top:30px}}p{{margin:14px 0}}a{{color:#146587}}.meta{{color:#657b85;font-size:14px}}.lead{{background:#fff0e7;border-left:5px solid #b9684c;padding:18px}}.note{{background:#fff4df;padding:15px;border-radius:8px}}.cards{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:20px 0}}.card{{padding:18px;background:#f0f5f6;border-radius:9px}}.big{{font-size:27px;font-weight:700;display:block}}img{{max-width:100%;height:auto;border:1px solid #dce6e9}}.scroll{{overflow:auto}}table{{width:100%;border-collapse:collapse;font-size:14px}}th,td{{padding:10px;border-bottom:1px solid #dce6e9;text-align:left;vertical-align:top}}th{{background:#eef3f5}}code{{overflow-wrap:anywhere}}@media(max-width:700px){{main{{margin:0;padding:20px 14px;border-radius:0}}h1{{font-size:25px}}.cards{{grid-template-columns:1fr}}table{{min-width:650px}}}}</style><main><p class="meta">2026-10-18 JST · 都心三区及必要道路连接 · 正常交通准入检查</p><h1>观测约束负荷未获准入，暴雨交通计算尚未启动</h1><div class="lead">已完成固定路径基底、85断面覆盖检查、三档诊断负荷草案和独立可行性检验。当前路径集合无法同时解释普通道路与高速观测，正常基线未通过预设规则。因此没有继续生成暴雨绕行、拥堵或人数结果，也没有追加水动力模拟。</div><div class="cards"><div class="card"><span class="big">80／85</span>有既有路径经过的观测断面</div><div class="card"><span class="big">±58.1%</span>80个有覆盖断面至少需要的统一误差界<br>预设仅允许±20%</div><div class="card"><span class="big">未获准入</span>低／中／高仅为诊断草案<br>正式暴雨交通分配未运行</div></div>
<h2>1. 本次执行到哪一步</h2><p>复用528个既有道路入口、75,398条扩展OD路径、原U成本、原单行与转向约束。一次全域路径追踪约{basis['seconds']:.1f}秒，包含约{basis['path_arc_entries']/1e6:.2f}百万次物理弧使用；原所有五个时段基础流量复现，最大差值{basis['prior_arc_replay_max']:.2g}，原最优成本差0秒。</p><p>原65和已查看20均为开发资料，本次全部用于情景约束，没有独立验证或重新封存。先检查能否用非负OD权重同时达到观测的80%–120%；只有通过才有资格进入受淹交通对照。±20%和低／中／高0.8／1.0／1.2倍均为研究敏感性假设，不是统计置信区间或官方精度承诺。</p>
<h2>2. 两种不同的障碍</h2><p><b>普通道路路径覆盖不足：</b>53个普通道路断面中有5个没有任何既有OD路径经过，合计68,145次小型车／12小时，占这批普通道路观测通过量约9.06%。它们保留为模型覆盖缺口，不能当成真实零流量；也不能通过给已有OD乘倍数恢复。</p><p><b>已有路径之间存在无法靠加量消除的约束矛盾：</b>当前路径集合要求模型A流量≤模型B流量；实际观测A=59,448，B=15,769。即使A只取观测的80%、B取120%，仍有47,558&gt;18,923，无法满足上述路径关系。这两个断面对应不同道路源段，没有发现它们被重复映射到完全相同的道路源段集合。</p><img src="baseline_gate_evidence.png" alt="Observed screenline support and incompatible fixed-route traffic constraints"><div class="scroll"><table><tr><th>观测段ID</th><th>来源道路</th><th>小型车／12h</th><th>最小最大误差证明中的作用</th></tr>{cert}</table></div><p>另一个独立线性规划允许所有候选路径组任意取非负交通量，不使用草案拟合的权重上限，仍证明80个有覆盖断面的最小统一误差界至少为±{gate['minimum_necessary_uniform_relative_error_band']:.2%}。因此失败并非仅由优化轮数、正则化或权重上限造成；这也不证明官方观测有错，不能据此推广到所有现实路线或所有可能OD。</p><p>{link('infeasible_constraint_certificate.csv','独立线性规划证据')} · {link('fixed_route_flow_dependency.csv','流量大小关系与观测冲突')} · {link('structural_coverage_summary.csv','普通道路与高速覆盖')} · {link('observation_route_support.csv','原85断面路径支持')}</p>
<h2>3. 保存了三档草案，但不能作为合格正常交通</h2><p>在可行性失败后，按预设回退规则保存带0.02–50倍权重界限的最小残差诊断。优化达到1,500轮上限，未收敛；64／80个有覆盖断面落入±20%。这些数值只展示当前模型可以怎样追随部分观测，不是可靠的交通负荷重建，未自动发布或替换原基线。</p><p>诊断中心情景12h候选权重约{fit['central_scenario12h_total']:,.0f}，原先验约{fit['source_prior12h_total']:,.0f}。约{fit['central_weight_share_at_ratio_above10']:.1%}的中心候选权重来自被放大超过10倍的原先验路径组，最大达到50倍边界。这进一步说明，不能把拟合出的量写成观测到的车辆需求。不可识别的零观测路径组保持原先验。</p><details><summary>查看未准入三档草案的观测贴合情况</summary><div class="scroll"><table><tr><th>草案</th><th>道路</th><th>模型／观测总量</th><th>WAPE</th><th>±20%内的有覆盖断面</th></tr>{rows}</table></div></details><p>低／高由同一诊断中心乘0.8／1.2生成；这种共同倍率本身不会改变固定路径或连通性，不可被当成对拥堵反馈稳定性的验证。原不明时刻、车型联合OD、出租车空驶和域外人员驾驶需求没有被这一步识别。原远端穿越池单独保留，没有悄悄合并成新增车辆。</p><p>{link('normal_observation_constraints.csv','全部断面与草案值')} · {link('normal_constraint_metrics.csv','诊断指标')} · {link('group_adjustment_diagnostics.csv','权重变化与不可识别项')} · {link('scenario_demand_totals.csv','草案时段总量')} · <a href="inverse_summary.json">可行性与优化状态</a></p>
<h2>4. 积水与容量接口准备完毕，未用失败草案计算交通后果</h2><p>已绑定既有E20250911__H__U、实际经过14,400秒的统一时刻，约2025-09-11 17:15 JST。它使用历史雷达雨场作参考，但H组河道抬升1.5 m是研究情景，不是历史实测河道过程。原12时刻及峰值包络没有混合，本轮只准备该同步时刻。</p><p>原共同证据支持28,064个道路源线段，其余387,891段为高程、域外或对应不足的未知。该时刻按预设0.3 m关闭、0.1–0.3 m减半服务能力／双倍时间假设，分别有3,457个已知源线段触发关闭、3,777段触发减速。三区相交关闭源线段完整长度约121.14 km；这是既有积水投影和研究阈值下的路段暴露，不是已证实的整路关闭长度，也不是新增车辆或受影响人数。</p><p>桥隧、高架与域外未知不被画成干路，已保存未知可用／未知暂不使用两个道路状态；未来每个分支都需有相同未知处理的正常对照。0.1／0.3 m、双倍时间和半容量是分析假设，不能当作认证涉水阈值或实测深度—速度定律。</p><p>85个精确来源断面均能从官方12h总流量和混杂度形成12h参考容量；未把它除以12当作小时容量。小型车成分／全车参考容量和大型车背景仍需分开，未观测道路继续未知，不能给每条道路编造小时容量或真实排队时长。</p><p>{link('capacity_reference_12h.csv','12h容量参考与单位')} · {link('flood_road_state_inventory.csv','既有积水接口')} · {link('protocol.json','阈值、未知分支与停止规则')}</p>
<h2>5. 后续应处理什么</h2><p>当前需先批量区分<b>OD空间支持不足、路径选择受限、路网连接或观测对应偏差</b>，重点解释5个普通道路零覆盖和高速流量大小关系。不能仅凭这次证据决定某一项就是原因，也不应删除冲突观测来制造通过。</p><p>下一项应是全域路径支持诊断：在固定成本与权限下，检查扩大可达起终点候选是否能覆盖缺口，及路径大小关系是否仍成立；同时保留官方观测与道路映射的独立核对。确认原因并解决后，再生成受约束负荷及同需求的正常／积水对照。本轮没有开启下一套路径模型或新假设分配。</p><p class="note">目前尚不能启动正式暴雨拥堵批量实验。已保存诊断代码、输入合同与失败证据，保证不会把正常模型的结构性误差误归因于暴雨。此次停止发生在预设正常基线准入阶段，暴雨交通分配、排队与受影响人数部分未完成。</p>
<h2>复现和完整性</h2><p>路径基底与独立失败证明共{counts}项完整性核验通过，表示失败结论可复现，<b>不表示交通模型通过准入</b>。来源文件、原成本、原道路图和已有水动力结果哈希保持不变。原始资料、AnaSOP、Git、DVC及既有实验没有改写。</p><p>顺序：<code>prepare_observed_load_pilot_v1.py</code> → <code>build_observed_load_basis_v1.py</code> → <code>fit_observed_load_scenarios_v1.py</code> → <code>diagnose_observed_load_gate_v1.py</code> → <code>report_observed_load_gate_v1.py</code>。预处理位于src/preprocessing，其余位于src/analyses。</p><p>{link('input_bindings.json','源输入哈希')} · <a href="basis_validation.json">路径复现核验</a> · <a href="feasibility_gate.json">准入失败与未执行项目</a> · <a href="validation.json">失败诊断完整性</a> · <a href="execution_state.json">执行状态</a> · <a href="{os.path.relpath(ROOT/'data/exp/estimation/three_ward_vehicle_demand_recovery_v1/review.html',R)}">上轮固定成本补需求</a></p><p class="meta">2018 PT、2021道路普查与2026路网的年份和车型差异保留。底层道路 © OpenStreetMap contributors / ODbL；数据出处沿用源审计。Framelog：MILI-D-20261018-007。</p></main></html>'''
 (R/'review.html').write_text(doc);files=list(P.glob('*'))+list(R.glob('*'))+[ROOT/'src/preprocessing/prepare_observed_load_pilot_v1.py']+[ROOT/'src/analyses'/n for n in ['observed_load_common_v1.py','build_observed_load_basis_v1.py','fit_observed_load_scenarios_v1.py','diagnose_observed_load_gate_v1.py','report_observed_load_gate_v1.py','validate_observed_load_gate_browser_v1.cjs']];dump(R/'delivery_manifest.json',{'created_utc':dt.datetime.now(dt.timezone.utc).isoformat(),'files':[{'path':str(p.relative_to(ROOT)),'bytes':p.stat().st_size,'sha256':sha(p)}for p in files if p.is_file()and p.name not in ['delivery_manifest.json','review_desktop.png','review_mobile.png','browser_validation.json']]});print('Failed-gate report complete; no qualified load or storm traffic claimed.')
if __name__=='__main__':main()
